/* The build joins domain.js, demo.js and this file into one offline-capable demo HTML. */
const DEMO=__DEMO__;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2,minimumFractionDigits:0}).format((Number(n)||0)/100);
const rupees=n=>((Number(n)||0)/100).toFixed(2);
const niceDate=d=>d?new Date(d+'T12:00:00+05:30').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'';
const timeText=d=>new Date(d).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'});
const ICONS={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M7 15h3M14 15h3"/>',receipt:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2zM9 7h6M9 11h6M9 15h4"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 4v2"/>',box:'<path d="m12 3 9 5v9l-9 5-9-5V8zM3 8l9 5 9-5M12 13v9M7 5l9 5"/>',scissors:'<circle cx="6" cy="6" r="3"/><circle cx="6" cy="18" r="3"/><path d="m8 8 12 12M8 16 20 4M12 12h.01"/>',wallet:'<path d="M20 8H5a2 2 0 0 1 0-4h14v4M5 8a2 2 0 0 1-2-2v12a2 2 0 0 0 2 2h15V8M20 12h-5v4h5"/>',chart:'<path d="M4 3v17h17M8 15v-4M13 15V7M18 15V4"/>',settings:'<path d="m10 3-1 3-3 1-2 4 2 2 1 4 3 1 3 3 3-3 3-1 1-4 2-2-2-4-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',refresh:'<path d="M20 7a9 9 0 1 0 0 10M20 3v5h-5"/>',logout:'<path d="M9 4H4v16h5M9 12h12m-4-4 4 4-4 4"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',trash:'<path d="M3 6h18M9 3h6M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',print:'<path d="M7 8V3h10v5M7 17H3V9h18v8h-4M7 14h10v7H7z"/>',shield:'<path d="m12 3 9 4v6c0 4-5 7-9 9-4-2-9-5-9-9V7zM8 12l3 3 5-6"/>',edit:'<path d="m14 5 5 5M4 20l5-1L21 7l-4-4L5 15z"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',leaf:'<path d="M20 3C4 2 2 11 7 17c6 6 15-1 13-14ZM6 20l10-12"/>',rupee:'<path d="M6 4h12M6 9h12M7 4c9 0 9 9 0 9l10 8"/>'};
const icon=(name)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">${ICONS[name]||ICONS.grid}</svg>`;
const btn=(label,act,cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${act}" ${attrs}>${label}</button>`;
const badge=(txt,kind='')=>`<span class="badge ${kind}">${esc(txt)}</span>`;
const empty=(title,msg,ico='box')=>`<div class="empty">${icon(ico)}<h3>${esc(title)}</h3><p>${esc(msg)}</p></div>`;
const title=(name,sub,action='')=>`<div class="page-header"><div><p class="eyebrow">Skynn & Soul / ${A.user?.role==='owner'?'Owner workspace':'Salon operations'}</p><h1>${name}</h1><p class="subtitle">${sub}</p></div><div class="actions">${action}</div></div>`;
const card=(heading,body,action='')=>`<section class="card"><div class="card-head"><h2>${heading}</h2>${action}</div>${body}</section>`;
const table=(headers,rows)=>rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty('Nothing here yet','New records will appear here.');
const stat=(label,value,note,ico,highlight=false)=>`<div class="stat ${highlight?'highlight':''}"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`;
const input=(name,label,value='',type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(name,label,options,value='',attrs='')=>`<label class="field">${label}<select name="${name}" aria-label="${esc(label)}" ${attrs}>${options.map(o=>{let [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;
const area=(name,label,value='')=>`<label class="field full">${label}<textarea name="${name}">${esc(value)}</textarea></label>`;
const check=(name,label,value=false)=>`<label class="check-label"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
const fields=(...items)=>`<div class="form-grid">${items.join('')}</div>`;
const methods=METHODS.map(m=>[m,m==='upi'?'UPI':m.charAt(0).toUpperCase()+m.slice(1)]);
const monthStart=()=>day().slice(0,7)+'-01';
const A={user:null,csrf:'',data:null,page:'dashboard',search:'',category:'All',catalogType:'service',catalogSearch:'',cart:[],draft:{customerId:'',discount:'0',discountReason:'',note:'',cash:'',upi:'',card:'',bank:''},date:day(),from:monthStart(),to:day(),report:'sales',financeTab:'expenses',importKind:'customers',importRows:[],importPrepared:null,staffDate:day(),savedAt:'',syncError:'',busy:false,role:'manager',tablePage:1,pending:null};
let toastTimer,poll;
function toast(message,error=false){$('#toast')?.remove();const el=document.createElement('div');el.id='toast';el.className='toast'+(error?' error':'');el.setAttribute('role','status');el.textContent=message;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),error?9000:4500);}
async function api(path,payload){const options={method:payload?'POST':'GET',credentials:'same-origin',headers:{}};if(payload){options.headers={'Content-Type':'application/json','X-CSRF-Token':A.csrf};options.body=JSON.stringify(payload);}const res=await fetch('/api/'+path,options);let data;try{data=await res.json();}catch{throw new Error('The secure server is not available. Follow SETUP.md before using real salon records.');}if(!res.ok){if(res.status===401&&path!=='login'){A.user=null;A.data=null;renderLogin(data.error);}throw new Error(data.error||'The request could not be completed.');}return data;}
async function mutate(type,payload){assert(!A.busy,'A save is already in progress.');const signature=JSON.stringify({type,payload});if(!A.pending||A.pending.signature!==signature)A.pending={signature,op:{id:uid(),type,payload}};const op=A.pending.op;A.busy=true;setSync('Saving…');try{let out;if(DEMO){const run=()=>{const current=JSON.parse(localStorage.getItem('skynn-soul-demo-v1')||'null')||A.data;out=applyOperation(current,op,A.user);localStorage.setItem('skynn-soul-demo-v1',JSON.stringify(out.state));};if(navigator.locks)await navigator.locks.request('skynn-soul-demo',run);else run();}else out=await api('action',op);A.data=out.state;A.pending=null;A.savedAt=out.savedAt||out.state.updatedAt;A.syncError='';setSync();return out.result;}catch(e){A.syncError=e.message;setSync();throw e;}finally{A.busy=false;}}
async function sync(silent=false){if(!A.user||A.busy)return;try{if(DEMO)A.data=JSON.parse(localStorage.getItem('skynn-soul-demo-v1'))||A.data;else{const r=await api('state');A.data=r.state;A.savedAt=r.savedAt;}A.syncError='';setSync();if(!$('#modal-root').children.length&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))renderPage();if(!silent)toast(DEMO?'Demo data refreshed':'Latest GitHub records loaded');}catch(e){A.syncError=e.message;setSync();if(!silent)toast(e.message,true);}}
function setSync(message){const el=$('#sync-state');if(!el)return;el.className='sync'+(A.syncError?' error':'');el.innerHTML=`<span class="dot"></span>${esc(message||(A.syncError?'Sync needs attention':DEMO?'Demo saved in this browser':A.savedAt?'Saved '+timeText(A.savedAt):'Connected to GitHub'))}`;el.title=A.syncError||'';}
function demoInit(){try{const prev=JSON.parse(localStorage.getItem('skynn-soul-demo-v1'));if(prev?.schema===SCHEMA)return prev;}catch{}const s=demoState();localStorage.setItem('skynn-soul-demo-v1',JSON.stringify(s));return s;}
function brand(){return `<div class="brand"><div class="brandmark">s</div><div class="brand-text"><strong>skynn & soul</strong><small>Salon workspace</small></div></div>`;}
function renderLogin(error=''){clearInterval(poll);document.getElementById('app').innerHTML=`<div class="login"><section class="login-art">${brand()}<div><p class="eyebrow" style="color:#c8b28b">More time for what you love</p><h1>A beautiful salon.<br>A simpler workday.</h1><p>Care for your clients. Keep your team in sync. Bring every part of your salon into one calm workspace.</p></div><div class="login-checks"><span>✓ Billing & stock</span><span>✓ Client care</span><span>✓ Clear business reports</span></div></section><main class="login-main"><div class="login-box"><p class="eyebrow">Welcome to Skynn & Soul</p><h2>Your salon, in one place.</h2><p class="subtitle">Choose your workspace to get started.</p><div class="role-cards"><button class="role-card ${A.role==='manager'?'selected':''}" data-action="choose-role" data-role="manager">${icon('scissors')}<strong>Salon manager</strong><small>Bookings, billing, clients<br>and daily operations</small></button><button class="role-card ${A.role==='owner'?'selected':''}" data-action="choose-role" data-role="owner">${icon('chart')}<strong>Salon owner</strong><small>Business insights, controls<br>and complete oversight</small></button></div><form id="login-form">${DEMO?'<div class="notice warn"><strong>Interactive demo</strong><br>Sample records only. Both roles share data in this browser. This file is not connected to GitHub and is not a secure live system.</div>':input('password','Password','','password','required autocomplete="current-password" minlength="1"')}<div id="login-error">${error?`<div class="form-error">${esc(error)}</div>`:''}</div><button class="btn primary" type="submit">${DEMO?'Open '+(A.role==='owner'?'owner':'manager')+' demo':'Sign in securely'} ${icon('arrow')}</button></form><p style="font-size:10px;color:var(--muted);margin-top:22px">${DEMO?'Try a bill, change stock or add a customer. Sign out and switch roles to see the same saved records.':'Your session stays on this device. Ask the owner if you need access.'}</p></div></main></div>`;}
const navs=[['dashboard','grid','Overview'],['billing','receipt','New bill'],['appointments','calendar','Appointments'],['customers','users','Customers'],['invoices','receipt','Invoices & dues'],['inventory','box','Inventory'],['services','scissors','Services & prices'],['finance','wallet','Expenses & purchases'],['team','users','Team & attendance'],['imports','upload','Import data'],['reports','chart','Reports'],['close','check','Day closing'],['settings','settings','Settings']];
function renderShell(){document.getElementById('app').innerHTML=`<div class="app"><aside class="sidebar" id="sidebar">${brand()}<button class="icon-button mobile-close" data-action="menu" aria-label="Close menu">${icon('close')}</button><div class="nav-label">WORKSPACE</div><nav>${navs.filter(n=>A.user.role==='owner'||!['settings','reports'].includes(n[0])).map(([id,ic,name])=>`<button class="nav-button ${A.page===id?'active':''}" data-page="${id}" data-action="nav" data-target="${id}" title="${name}">${icon(ic)}<span>${name}</span></button>`).join('')}</nav><div class="side-foot"><div class="side-card"><strong>Every detail, in balance.</strong><p style="margin:5px 0 0;color:var(--muted)">Your team and your business, working beautifully together.</p></div><div class="user-row"><div class="avatar">${A.user.role==='owner'?'SO':'SM'}</div><div><strong>${esc(A.user.name)}</strong><small>${A.user.role==='owner'?'Owner access':'Manager access'}</small></div><button class="icon-button" data-action="logout" style="margin-left:auto" title="Sign out" aria-label="Sign out">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="actions"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open menu">${icon('menu')}</button><div class="crumb">Workspace &nbsp; / &nbsp; <b id="crumb-title">Overview</b></div></div><div class="top-actions"><span id="sync-state" class="sync"></span><button class="icon-button" data-action="refresh" title="Refresh shared data" aria-label="Refresh shared data">${icon('refresh')}</button><span class="badge gray">${A.user.role==='owner'?'Owner':'Manager'}</span><button class="icon-button" data-action="logout" title="Sign out" aria-label="Sign out">${icon('logout')}</button></div></header>${DEMO?`<div class="demo-banner"><span><strong>DEMO WORKSPACE</strong> · Fictional sample data. Changes stay in this browser.</span><button data-action="reset-demo">Reset sample data</button></div>`:''}<div class="page" id="page"></div></main></div>`;setSync();renderPage();clearInterval(poll);poll=setInterval(()=>{if(!document.hidden)sync(true);},60000);}
function go(page){if(A.cart.length&&A.page==='billing'&&page!=='billing'&&!confirm('Keep your unsaved bill and move to another screen?'))return;A.page=page;A.search='';A.tablePage=1;$('#sidebar')?.classList.remove('open');renderPage();}
function renderPage(){if(!A.user||!A.data)return;document.querySelectorAll('[data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page===A.page));$('#crumb-title').textContent=navs.find(x=>x[0]===A.page)?.[2]||'Workspace';const views={dashboard:dashboardView,billing:billingView,appointments:appointmentsView,customers:customersView,invoices:invoicesView,inventory:inventoryView,services:servicesView,finance:financeView,team:teamView,imports:importsView,reports:reportsView,settings:settingsView,close:closeView};$('#page').innerHTML=(views[A.page]||dashboardView)();}
function searchBar(placeholder,extra=''){return `<div class="filter-bar"><div class="searchbox">${icon('search')}<input id="list-search" placeholder="${esc(placeholder)}" value="${esc(A.search)}" aria-label="${esc(placeholder)}"></div>${extra}</div>`;}
const matches=(r,keys)=>!A.search||keys.map(k=>r[k]).join(' ').toLowerCase().includes(A.search.toLowerCase());
function pageRows(rows,render){const count=25,total=Math.max(1,Math.ceil(rows.length/count));A.tablePage=Math.min(A.tablePage,total);const part=rows.slice((A.tablePage-1)*count,A.tablePage*count);return {rows:part.map(render),foot:`<div class="pagination"><span>${rows.length} records · page ${A.tablePage} of ${total}</span><div class="actions">${btn('Previous','prev-page','small',A.tablePage<=1?'disabled':'')}${btn('Next','next-page','small',A.tablePage>=total?'disabled':'')}</div></div>`};}
function invoiceStatus(inv){if(inv.status==='void')return badge('Cancelled','red');const due=balance(A.data,inv.id);return due>0?badge('Due '+money(due),'warn'):badge('Paid');}
function invoiceRows(list){return list.map(i=>`<tr><td><button class="subtle-link" data-action="view-invoice" data-id="${i.id}">${esc(i.number)}</button></td><td>${esc(i.customerName)}<div class="cell-sub">${esc(i.customerPhone)}</div></td><td>${niceDate(i.date)}</td><td>${invoiceStatus(i)}</td><td class="amount">${money(i.total)}</td><td>${btn('View','view-invoice','small',`data-id="${i.id}"`)}</td></tr>`);}
function dashboardView(){const s=A.data,today=day(),m=metrics(s,today,today),monthly=metrics(s,monthStart(),today),apps=s.appointments.filter(a=>a.date===today&&a.status!=='cancelled').sort((a,b)=>a.start-b.start);const low=s.products.filter(p=>active(p)&&p.stock<=p.reorder);const recent=[...s.invoices].reverse().slice(0,5);let dates=[];for(let i=13;i>=0;i--)dates.push(day(new Date(Date.now()-i*86400000)));const range=metrics(s,dates[0],today);const values=dates.map(d=>range.daily.find(x=>x[0]===d)?.[1]||0);const max=Math.max(...values,1);return title(`A good day starts here.`,`Here's what's happening at your salon today, ${niceDate(today)}.`,`${btn(icon('calendar')+'Appointments','nav','',`data-target="appointments"`)}${btn(icon('plus')+'New bill','nav','primary',`data-target="billing"`)}`)+`<div class="stats">${stat("Today's sales",money(m.sales),m.invoices.length+' completed bills','rupee',true)}${stat('Money received',money(m.collections),'Cash, UPI, card & bank','wallet')}${stat("Today's bookings",apps.length,apps.filter(x=>x.status==='booked').length+' upcoming appointments','calendar')}${stat('Customer dues',money(m.outstanding),'Outstanding across all dates','receipt')}</div><div class="grid-2">${card('Sales at a glance',`<div class="card-body"><div class="actions" style="justify-content:space-between"><div><div class="stat-value" style="margin:0">${money(monthly.net)}</div><small>This month · sales before tax</small></div>${badge('Last 14 days','gray')}</div><div class="chart">${dates.map((d,i)=>`<div class="bar-col"><div class="bar" style="height:${Math.max(values[i]/max*100,1)}%"><span class="chart-tip">${niceDate(d)} · ${money(values[i])}</span></div><span class="bar-label">${i%2===0||i===13?d.slice(8):''}</span></div>`).join('')}</div></div>`,A.user.role==='owner'?btn('View reports '+icon('arrow'),'nav','small',`data-target="reports"`):'')}${card("Today's appointments",`<div class="card-body">${apps.length?apps.slice(0,4).map(a=>`<div class="list-row"><div class="avatar">${esc(a.customerName.slice(0,2).toUpperCase())}</div><div><p>${esc(a.customerName)}</p><small>${esc(a.serviceName)} · ${esc(a.staffName)}</small></div><div class="right"><strong>${a.time}</strong><div>${badge(a.status,a.status==='booked'?'warn':'')}</div></div></div>`).join(''):empty('A little room to grow','Add a booking or follow up with a client.','calendar')}</div>`,btn(icon('plus'),'new-appointment','small','aria-label="Add appointment"'))}</div><div class="grid-2">${card('Recent bills',table(['Bill','Customer','Date','Status','Total',''],invoiceRows(recent)),btn('All bills '+icon('arrow'),'nav','small',`data-target="invoices"`))}${card('A little attention needed',`<div class="card-body">${low.length?low.slice(0,3).map(p=>`<div class="list-row">${icon('box')}<div><p>${esc(p.name)}</p><small>${p.stock} ${esc(p.unit)} left · reorder at ${p.reorder}</small></div><div class="right">${badge('Low stock','warn')}</div></div>`).join(''):'<div class="notice">Stock levels look healthy.</div>'}<div class="mini-grid" style="margin-top:17px"><div class="mini"><small>Cash</small><strong>${money(m.byMethod.cash)}</strong></div><div class="mini"><small>UPI</small><strong>${money(m.byMethod.upi)}</strong></div><div class="mini"><small>Card</small><strong>${money(m.byMethod.card)}</strong></div></div><p class="subtitle" style="margin-top:15px">${s.closures.some(c=>c.date===today&&!c.reopenedAt)?'Day closing recorded.':'Remember to complete the day closing before you leave.'}</p></div>`,btn('Stock '+icon('arrow'),'nav','small',`data-target="inventory"`))}</div>`;}
function customersView(){const s=A.data,rows=s.customers.filter(c=>matches(c,['name','phone','email'])).sort((a,b)=>a.name.localeCompare(b.name));const page=pageRows(rows,c=>{const inv=s.invoices.filter(i=>i.customerId===c.id&&i.status==='posted');return `<tr><td><div class="cell-main">${esc(c.name)}</div><div class="cell-sub">${esc(c.email)}</div></td><td>${esc(c.phone||'Not provided')}</td><td>${inv.length}</td><td>${c.membershipUntil&&c.membershipUntil>=day()?badge('Member until '+niceDate(c.membershipUntil)):badge('Standard','gray')}</td><td class="amount">${money(inv.reduce((n,i)=>n+i.total,0))}</td><td>${btn('History','customer-history','small',`data-id="${c.id}"`)} ${btn('Edit','edit-customer','small',`data-id="${c.id}"`)}</td></tr>`;});return title('Customers','Remember every visit. Make the next one even better.',btn(icon('plus')+'Add customer','new-customer','primary'))+card('Your client book',searchBar('Search name, phone or email',btn(icon('upload')+'Import CSV','nav','small','data-target="imports"'))+table(['Customer','Phone','Visits','Membership','Total billed',''],page.rows)+page.foot);}
function servicesView(){const s=A.data,rows=s.services.filter(x=>matches(x,['name','category']));return title('Services & prices','A clear menu, consistent prices and the right products for every service.',A.user.role==='owner'?btn(icon('plus')+'Add service','new-service','primary'):'')+card('Service menu',searchBar('Search services or categories')+table(['Service','Category','Time','Price','Tax','Status',''],rows.map(x=>`<tr><td><div class="cell-main">${esc(x.name)}</div><div class="cell-sub">${(x.recipe||[]).length} linked stock items</div></td><td>${esc(x.category)}</td><td>${x.duration} min</td><td>${money(x.price)}</td><td>${x.taxBps/100}%</td><td>${badge(active(x)?'Active':'Inactive',active(x)?'':'gray')}</td><td>${A.user.role==='owner'?btn('Edit','edit-service','small',`data-id="${x.id}"`):''}</td></tr>`)));}
function inventoryView(){const s=A.data,rows=s.products.filter(x=>matches(x,['name','sku','category']));const low=s.products.filter(x=>active(x)&&x.stock<=x.reorder),value=s.products.reduce((n,x)=>n+x.stock*x.cost,0);const page=pageRows(rows,p=>`<tr><td><div class="cell-main">${esc(p.name)}</div><div class="cell-sub">${esc(p.sku)} · ${p.retail?'Retail & service use':'Salon use'}</div></td><td>${p.stock} ${esc(p.unit)}</td><td>${p.reorder}</td><td>${money(p.cost)}</td><td>${p.expiry?niceDate(p.expiry):'Not set'}</td><td>${p.expiry&&p.expiry<day()?badge('Expired','red'):!active(p)?badge('Inactive','gray'):p.stock<=p.reorder?badge('Low stock','warn'):badge('In stock')}</td><td><div class="actions">${btn('Receive','receive-stock','small',`data-id="${p.id}"`)}${btn('Adjust','adjust-stock','small',`data-id="${p.id}"`)}${btn('History','stock-history','small',`data-id="${p.id}"`)}${A.user.role==='owner'?btn('Edit','edit-product','small',`data-id="${p.id}"`):''}</div></td></tr>`);return title('Inventory','Know what you have. Order before you run out.',A.user.role==='owner'?btn(icon('plus')+'Add product','new-product','primary'):'')+`<div class="stats">${stat('Products',s.products.length,'Registered stock items','box')}${stat('Low stock',low.length,'At or below reorder level','clock')}${stat('Stock value',money(Math.round(value)),'At recorded unit cost','wallet')}${stat('Retail products',s.products.filter(p=>p.retail&&active(p)).length,'Available at the billing counter','receipt')}</div>`+card('Stock on hand',searchBar('Search name, SKU or category')+table(['Product','Available','Reorder at','Unit cost','Expiry','Status','Actions'],page.rows)+page.foot);}
function appointmentsView(){const s=A.data,rows=s.appointments.filter(x=>x.date===A.date&&matches(x,['customerName','serviceName','staffName'])).sort((a,b)=>a.start-b.start);return title('Appointments','A smooth schedule, from the first welcome to the last goodbye.',btn(icon('plus')+'New appointment','new-appointment','primary'))+card('Salon schedule',searchBar('Search customer, service or staff',`<input type="date" id="appointment-date" value="${A.date}" aria-label="Appointment date">`)+table(['Time','Customer','Service','Team member','Status',''],rows.map(a=>`<tr><td><strong>${a.time}</strong><div class="cell-sub">${a.duration} min</div></td><td>${esc(a.customerName)}</td><td>${esc(a.serviceName)}</td><td>${esc(a.staffName)}</td><td>${badge(a.status,['cancelled','no-show'].includes(a.status)?'gray':a.status==='booked'?'warn':'')}</td><td>${btn('Edit','edit-appointment','small',`data-id="${a.id}"`)} ${!a.invoiceId&&a.status!=='cancelled'?btn('Bill','bill-appointment','small',`data-id="${a.id}"`):''}</td></tr>`)));}
function invoicesView(){const rows=[...A.data.invoices].reverse().filter(i=>matches(i,['number','customerName','customerPhone']));const page=pageRows(rows,i=>invoiceRows([i])[0]);return title('Invoices & customer dues','Every bill, every payment and every balance in one place.',btn(icon('plus')+'New bill','nav','primary','data-target="billing"'))+card('Billing history',searchBar('Search bill, customer or phone')+table(['Bill','Customer','Date','Status','Total',''],page.rows)+page.foot);}
function billPayload(){const payload={lines:A.cart,customerId:A.draft.customerId,discount:paise(A.draft.discount||'0'),discountReason:A.draft.discountReason,note:A.draft.note,appointmentId:A.draft.appointmentId||'',payments:METHODS.map(m=>({method:m,amount:paise(A.draft[m]||'0')}))};if(payload.lines.length)payload.expectedTotal=quote(A.data,payload,A.user).total;return payload;}
function billQuote(){try{return {q:quote(A.data,billPayload(),A.user)};}catch(e){return {error:e.message};}}
function billingView(){const s=A.data,list=(A.catalogType==='service'?s.services:s.products.filter(p=>p.retail)).filter(active),cats=['All',...new Set(list.map(x=>x.category))],filtered=list.filter(x=>(A.category==='All'||x.category===A.category)&&x.name.toLowerCase().includes(A.catalogSearch.toLowerCase()));return title('Create a bill','Choose services, add a customer and record the payment.',A.cart.length?btn('Clear bill','clear-bill',''): '')+`<div class="bill-layout"><section><div class="card"><div class="card-body"><div class="tabs">${['service','product'].map(t=>btn(t==='service'?'Services':'Retail products','catalog-type',A.catalogType===t?'active':'',`data-type="${t}"`)).join('')}</div><label class="search">${icon('search')}<input id="catalog-search" placeholder="Find a service or product" value="${esc(A.catalogSearch)}"></label><div class="chips">${cats.map(c=>btn(esc(c),'category',A.category===c?'active':'',`data-value="${esc(c)}"`)).join('')}</div><div class="catalog-grid">${filtered.length?filtered.map(x=>`<button class="catalog-item" data-action="add-cart" data-id="${x.id}" data-kind="${A.catalogType}"><span class="catalog-icon">${icon(A.catalogType==='service'?'scissors':'box')}</span><strong>${esc(x.name)}</strong><small>${esc(x.category)} · ${x.duration?x.duration+' min':x.stock+' '+esc(x.unit)+' left'}</small><div>${money(x.price)}<span>+</span></div></button>`).join(''):empty('No matching items','Add your service menu or try another search.')}</div></div></div><div class="notice" style="margin-top:16px">Service products are removed from stock automatically when you save a bill. Set these links in Services & prices.</div></section><aside id="bill-summary">${billSummary()}</aside></div>`;}
function billSummary(){const s=A.data,{q,error}=billQuote();const paid=METHODS.reduce((n,m)=>n+(Number(A.draft[m])||0)*100,0);return `<section class="card bill-card"><div class="card-head"><h2>Current bill</h2>${badge(A.cart.length+' items','gray')}</div><div class="card-body"><label class="field">Customer<select id="bill-customer"><option value="">Walk-in customer</option>${s.customers.filter(active).sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<option value="${c.id}" ${c.id===A.draft.customerId?'selected':''}>${esc(c.name)} · ${esc(c.phone)}</option>`).join('')}</select></label>${btn('+ Add customer','new-customer','text-btn')}<div class="cart">${A.cart.length?A.cart.map((l,i)=>{const item=find(s,l.kind==='service'?'services':'products',l.id);return `<div class="cart-row"><div class="cart-main"><strong>${esc(item.name)}</strong>${btn(icon('close'),'remove-cart','icon-btn',`data-index="${i}" aria-label="Remove ${esc(item.name)}"`)}</div><div class="cart-controls"><div class="qty">${btn('−','qty-down','',`data-index="${i}"`)}<span>${l.qty}</span>${btn('+','qty-up','',`data-index="${i}"`)}</div><span>${money(item.price*l.qty)}</span></div><select class="cart-staff" data-cart-index="${i}" aria-label="Staff for ${esc(item.name)}"><option value="">Assign team member</option>${s.staff.filter(active).map(st=>`<option value="${st.id}" ${st.id===l.staffId?'selected':''}>${esc(st.name)}</option>`).join('')}</select></div>`;}).join(''):empty('Your bill starts here','Select a service from the menu.','receipt')}</div>${fields(input('bill-discount','Discount (₹)',A.draft.discount,'number','min="0" step="0.01" data-draft="discount"'),input('bill-reason','Reason for discount',A.draft.discountReason,'text','data-draft="discountReason"'))}<div class="totals"><div><span>Menu total</span><strong>${money(q?.subtotal||0)}</strong></div><div><span>Discount</span><span>− ${money(q?.discount||0)}</span></div><div><span>${esc(s.settings.taxLabel)} ${s.settings.taxMode==='inclusive'?'(included)':''}</span><span>${money(q?.tax||0)}</span></div><div class="grand"><span>Total</span><strong>${money(q?.total||0)}</strong></div></div><div class="actions" style="margin:12px 0">${btn('All cash','fill-payment','small','data-method="cash"')}${btn('All UPI','fill-payment','small','data-method="upi"')}${btn('All card','fill-payment','small','data-method="card"')}</div><div class="form-grid">${METHODS.map(m=>input('pay-'+m,m==='upi'?'UPI (₹)':m[0].toUpperCase()+m.slice(1)+' (₹)',A.draft[m],'number',`min="0" step="0.01" data-draft="${m}"`)).join('')}</div><p class="due-line" id="bill-due">${q?`Balance due: ${money(q.total-Math.round(paid))}`:'Select items to calculate the total.'}</p><label class="field">Bill note<input data-draft="note" value="${esc(A.draft.note)}" placeholder="Optional"></label>${error&&A.cart.length?`<div class="form-error">${esc(error)}</div>`:''}<button type="button" class="btn primary full-width" data-action="save-bill" ${!A.cart.length||error?'disabled':''}>${icon('check')} Save bill & payment</button><p class="fine-print">Only saved bills count in reports. A payment entry records money you have already received.</p></div></section>`;}
function financeView(){const s=A.data,expenses=[...s.expenses].reverse(),purchases=[...s.purchases].reverse(),m=metrics(s,monthStart(),day());return title('Expenses & purchases','Keep every payment and purchase bill in order.',btn(icon('plus')+(A.financeTab==='expenses'?'Add expense':'Receive stock'),A.financeTab==='expenses'?'new-expense':'receive-stock','primary'))+`<div class="stats">${stat('Expenses this month',money(m.expensesTotal),'Recorded operating expenses','wallet')}${stat('Purchases this month',money(m.purchasesTotal),'Stock received by purchase date','box')}${stat('Supplier payments',money(m.purchasesPaid),'Money paid this month','rupee')}${stat('Supplier dues',money(s.purchases.reduce((n,p)=>n+p.total-p.paid,0)),'Across all purchases','clock')}</div>`+card('Money out',`<div class="filters tabs">${btn('Expenses','finance-tab',A.financeTab==='expenses'?'active':'','data-tab="expenses"')}${btn('Stock purchases','finance-tab',A.financeTab==='purchases'?'active':'','data-tab="purchases"')}</div>`+(A.financeTab==='expenses'?table(['Date','Expense','Paid to','Method','Amount','Receipt'],expenses.map(x=>`<tr><td>${niceDate(x.date)}</td><td><strong>${esc(x.description)}</strong><div class="cell-sub">${esc(x.category)}</div></td><td>${esc(x.payee)}</td><td>${esc(x.method.toUpperCase())}</td><td>${money(x.amount)}</td><td>${x.attachment?btn('View receipt','attachment','small',`data-id="${x.id}" data-collection="expenses"`):esc(x.receipt||'—')}</td></tr>`)):table(['Date / bill','Product / supplier','Quantity','Total','Paid / due',''],purchases.map(p=>`<tr><td>${niceDate(p.date)}<div class="cell-sub">${esc(p.billNumber)}</div></td><td>${esc(p.productName)}<div class="cell-sub">${esc(p.supplier)}</div></td><td>${p.qty}</td><td>${money(p.total)}</td><td>${money(p.paid)} paid<div class="cell-sub">${money(p.total-p.paid)} due</div></td><td>${p.paid<p.total?btn('Pay due','pay-supplier','small',`data-id="${p.id}"`):''} ${p.attachment?btn('Receipt','attachment','small',`data-id="${p.id}" data-collection="purchases"`):''}</td></tr>`))));}
function teamView(){const s=A.data,m=metrics(s,monthStart(),day());return title('Team & attendance','Keep leave records clear and recognise good work.',A.user.role==='owner'?btn(icon('plus')+'Add team member','new-staff','primary'):'')+card('Daily attendance',`<div class="filters"><label class="field">Date<input type="date" id="staff-date" value="${A.staffDate}"></label><p class="subtitle">Choose a status and save it for each team member.</p></div>`+table(['Team member','Role','Status','Note',''],s.staff.filter(active).map(st=>{const a=s.attendance.find(x=>x.staffId===st.id&&x.date===A.staffDate);return `<tr><td><strong>${esc(st.name)}</strong><div class="cell-sub">${esc(st.phone)}</div></td><td>${esc(st.role)}</td><td><select id="att-${st.id}">${['present','leave','absent','half-day','weekly-off'].map(v=>`<option ${a?.status===v?'selected':''}>${v}</option>`).join('')}</select>${a?badge('Saved','gray'):badge('Not saved','warn')}</td><td><input id="att-note-${st.id}" value="${esc(a?.note||'')}" placeholder="Optional note"></td><td>${btn('Save','save-attendance','small',`data-id="${st.id}"`)} ${A.user.role==='owner'?btn('Edit','edit-staff','small',`data-id="${st.id}"`):''}</td></tr>`;})))+(A.user.role==='owner'?card('Incentives this month',`<div class="card-body"><p class="subtitle">Calculated on each assigned bill line after discount and before tax. These are earned amounts, not payroll payments.</p></div>`+table(['Team member','Rate now','Assigned sales','Earned incentive'],s.staff.map(st=>{const r=m.staffTotals.find(x=>x.id===st.id);return `<tr><td>${esc(st.name)} ${!active(st)?badge('Inactive','gray'):''}</td><td>${st.incentiveBps/100}%</td><td>${money(r?.net||0)}</td><td>${money(r?.incentive||0)}</td></tr>`;}))):'');}
const TEMPLATE={customers:'name,phone,email,birthday,membership_until,marketing_consent,notes\nSample Client,9000000001,,1990-01-15,,no,Sample only\n',services:'name,category,price,duration_minutes,tax_percent\nSample Haircut,Hair,500,45,0\n',products:'name,sku,category,unit,sale_price,cost_price,opening_stock,reorder_level,retail,supplier,expiry,tax_percent\nSample Shampoo,SH-001,Hair,bottle,500,300,10,3,yes,Sample Supplier,,0\n'};
function importsView(){return title('Import your data','Upload customer details, service prices and opening stock from a CSV file.')+`<div class="grid-2">${card('1. Choose and check',`<div class="card-body">${select('import-kind','What are you uploading?',A.user.role==='owner'?[['customers','Customers'],['services','Services & prices'],['products','Products & opening stock']]:[['customers','Customers']],A.importKind,'id="import-kind"')}<p class="subtitle">Start with the template. Keep the column names. Prices are in rupees. Use YYYY-MM-DD for dates.</p><div style="margin:18px 0">${btn(icon('download')+'Download CSV template','download-template','')}</div><label class="upload-zone">${icon('upload')}<strong>Choose your CSV file</strong><small>Up to 500 rows · 2 MB · new records only</small><input type="file" id="import-file" accept=".csv,text/csv"></label><p class="fine-print">Duplicate customer phone numbers and product SKUs are blocked. To change an existing price, edit it in Services & prices.</p></div>`)}${card('2. Review and import',`<div class="card-body">${A.importPrepared?`<div class="notice">${A.importPrepared.length} rows checked. Nothing has been saved yet.</div><p class="subtitle" style="margin:16px 0">The full file will be checked again when saved. If any row fails, no rows from this import are saved.</p>${btn(icon('check')+'Import '+A.importPrepared.length+' records','confirm-import','primary')}`:empty('Preview comes first','Choose a CSV file to review the first 10 rows.','upload')}</div>`)}</div>${A.importRows.length?card('File preview · first 10 rows',table(Object.keys(A.importRows[0]).map(esc),A.importRows.slice(0,10).map(r=>`<tr>${Object.values(r).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`))):''}`;}
function reportData(){const s=A.data,m=metrics(s,A.from,A.to),range=x=>x.date>=A.from&&x.date<=A.to,asMoney=n=>rupees(n);switch(A.report){case 'sales':return {h:['Date','Invoice','Customer','Before tax (₹)','Tax (₹)','Total (₹)','Due (₹)'],r:m.invoices.map(i=>[i.date,i.number,i.customerName,asMoney(i.net),asMoney(i.tax),asMoney(i.total),asMoney(balance(s,i.id))])};case 'payments':return {h:['Date','Invoice','Method','Amount (₹)','Reference'],r:m.payments.map(p=>[p.date,p.invoiceNumber,p.method,asMoney(p.amount),p.reference])};case 'services':return {h:['Item','Type','Quantity','Sales before tax (₹)'],r:m.serviceTotals.map(r=>[r.name,r.kind,r.qty,asMoney(r.net)])};case 'staff':return {h:['Team member','Items','Sales before tax (₹)','Earned incentive (₹)'],r:m.staffTotals.map(r=>[r.name,r.services,asMoney(r.net),asMoney(r.incentive)])};case 'customers':return {h:['Customer','Phone','Visits','Total (₹)','Due (₹)','Last visit','Marketing consent'],r:s.customers.map(c=>{const inv=m.invoices.filter(i=>i.customerId===c.id);return [c.name,c.phone,inv.length,asMoney(inv.reduce((n,i)=>n+i.total,0)),asMoney(s.invoices.filter(i=>i.customerId===c.id).reduce((n,i)=>n+balance(s,i.id),0)),inv.map(i=>i.date).sort().at(-1)||'',c.marketingConsent?'Yes':'No'];})};case 'stock':return {h:['SKU','Product','Current stock','Unit','Reorder at','Used in period','Daily use','Days left','Suggested order','Target cover (days)'],r:s.products.map(p=>{const used=-s.stockMoves.filter(x=>x.productId===p.id&&range(x)&&x.delta<0&&x.ref!=='adjustment').reduce((n,x)=>n+x.delta,0);const days=Math.max(1,(Date.parse(A.to)-Date.parse(A.from))/86400000+1),daily=used/days;return [p.sku,p.name,p.stock,p.unit,p.reorder,used.toFixed(3),daily.toFixed(3),daily?(p.stock/daily).toFixed(1):'No use',Math.max(0,Math.ceil(Math.max(p.reorder,daily*14)-p.stock)),14];})};case 'expenses':return {h:['Date','Category','Description','Paid to','Method','Amount (₹)','Receipt'],r:m.expenses.map(x=>[x.date,x.category,x.description,x.payee,x.method,asMoney(x.amount),x.receipt])};case 'purchases':return {h:['Date','Bill','Supplier','Product','Qty','Total (₹)','Paid to date (₹)','Due (₹)'],r:m.purchases.map(x=>[x.date,x.billNumber,x.supplier,x.productName,x.qty,asMoney(x.total),asMoney(x.paid),asMoney(x.total-x.paid)])};case 'attendance':return {h:['Date','Team member','Status','Note'],r:s.attendance.filter(range).map(x=>[x.date,s.staff.find(st=>st.id===x.staffId)?.name||'',x.status,x.note])};case 'closing':return {h:['Date','Expected cash (₹)','Actual (₹)','Difference (₹)','Closed by','Status','Note'],r:s.closures.filter(range).map(x=>[x.date,asMoney(x.expected),asMoney(x.actual),asMoney(x.difference),x.by,x.reopenedAt?'Reopened':'Closed',x.note])};case 'audit':return {h:['Time','User','Role','Action','Record','Details'],r:s.audit.filter(x=>day(x.at)>=A.from&&day(x.at)<=A.to).reverse().map(x=>[x.at,x.by,x.role,x.action,x.recordId,x.summary])};default:return {h:[],r:[]};}}
function reportsView(){if(A.user.role!=='owner')return empty('Owner access required','Sign in as the owner.','shield');const m=metrics(A.data,A.from,A.to),r=reportData();return title('Business reports','A clear view of your salon, with figures you can trace back to each bill.',`${btn(icon('download')+'Export CSV','export-report','')}${btn(icon('print')+'Print / PDF','print-report','')}`)+`<div class="card filters">${input('report-from','From',A.from,'date','id="report-from"')}${input('report-to','To',A.to,'date','id="report-to"')}${select('report-type','Report',[['sales','Sales & tax'],['payments','Money received / refunds'],['services','Services & retail'],['staff','Staff performance & incentives'],['customers','Customers & dues'],['stock','Stock & order planning'],['expenses','Expenses'],['purchases','Purchases & supplier dues'],['attendance','Attendance & leaves'],['closing','Daily closings'],['audit','Change history']],A.report,'id="report-type"')}</div><div class="stats">${stat('Sales before tax',money(m.net),m.invoices.length+' active bills in this period','chart',true)}${stat('Money received',money(m.collections),'Includes refunds as negative amounts','wallet')}${stat('Expenses',money(m.expensesTotal),'Operating costs in this period','rupee')}${stat('After stock & expenses',money(m.contribution),'Not full accounting profit','chart')}</div><div class="notice" style="margin-bottom:18px">Tax: ${money(m.tax)} · Discounts: ${money(m.discount)} · Stock used at cost: ${money(m.cost)} · Customer dues across all dates: ${money(m.outstanding)}. ${A.report==='stock'?'Suggested orders cover 14 days at the selected period’s average use. Check supplier delivery time before ordering.':'Cancelled bills are excluded from sales; refunds appear on the date paid.'}</div>`+card('Report details',table(r.h.map(esc),r.r.map(row=>`<tr>${row.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`)))+`<p class="fine-print">Live figures from saved records. Customer visits and value use the selected period; customer dues and stock balances are current. Incentives are earned estimates. Tax reports do not replace statutory returns.</p>`;}
function settingsView(){if(A.user.role!=='owner')return empty('Owner access required','Sign in as the owner.');const s=A.data.settings;return title('Salon settings','Your details, bill format and owner controls.')+card('Business & billing',`<form id="settings-form" class="card-body">${fields(input('salonName','Salon name',s.salonName,'text','required maxlength="100"'),input('phone','Phone',s.phone,'tel'),area('address','Address',s.address),input('gstin','GSTIN (if applicable)',s.gstin),input('invoicePrefix','Invoice prefix',s.invoicePrefix,'text','required maxlength="10"'),input('taxLabel','Tax label',s.taxLabel),select('taxMode','Price display',[['exclusive','Tax is added to menu price'],['inclusive','Tax is included in menu price']],s.taxMode),input('defaultTaxPercent','Default tax for new items (%)',s.defaultTaxBps/100,'number','min="0" max="100" step="0.01"'),input('managerDiscountPercent','Maximum manager discount (%)',s.managerDiscountBps/100,'number','min="0" max="100" step="0.01"'),area('receiptNote','Receipt message',s.receiptNote))}<div class="notice warn" style="margin:18px 0">Tax is 0% until you set it. Ask your accountant which rates and invoice details apply to your salon. Existing bills keep their original prices and tax details.</div><button class="btn primary" type="submit">Save settings</button></form>`)+card('Backup & access',`<div class="card-body"><p class="subtitle">Download a full JSON copy of all records. It contains private customer and business details; keep it in a safe place.</p><div style="margin:15px 0">${btn(icon('download')+'Download full backup','backup','')}</div><p class="fine-print">Production passwords are set on the server, never in this page. Use the setup script to change them, update the server secrets and increase SESSION_EPOCH to sign out all devices. To restore a backup, use the included restore script with a verified backup file.</p></div>`);}
function closingNumbers(values={}){const s=A.data,d=day(),cash=s.payments.filter(x=>x.date===d&&x.method==='cash').reduce((n,x)=>n+x.amount,0),out=s.expenses.filter(x=>x.date===d&&x.method==='cash').reduce((n,x)=>n+x.amount,0)+(s.vendorPayments||[]).filter(x=>x.date===d&&x.method==='cash').reduce((n,x)=>n+x.amount,0);return {cash,out,expected:(Number(values.opening||0)+Number(values.added||0)-Number(values.withdrawn||0))*100+cash-out};}
function closeView(){const existing=A.data.closures.find(c=>c.date===day()&&!c.reopenedAt),n=closingNumbers();return title('Day closing','Count the cash. Check the records. End the day with confidence.')+`<div class="grid-2">${card('Today · '+niceDate(day()),existing?`<div class="card-body"><div class="notice"><strong>Day closed by ${esc(existing.by)}</strong><br>Actual cash: ${money(existing.actual)} · Difference: ${money(existing.difference)}</div><p class="subtitle" style="margin:18px 0">Money records for this date are locked. The owner can reopen the day if a correction is needed.</p>${A.user.role==='owner'?btn('Reopen day','reopen-day','',`data-id="${existing.id}"`):''}</div>`:`<form id="close-form" class="card-body"><div class="notice">Cash received: ${money(n.cash)}<br>Cash spent on expenses and purchases: ${money(n.out)}</div>${fields(input('opening','Opening cash (₹)','0','number','required min="0" step="0.01"'),input('added','Other cash added (₹)','0','number','min="0" step="0.01"'),input('withdrawn','Cash taken out / bank deposit (₹)','0','number','min="0" step="0.01"'),input('actual','Cash counted now (₹)','','number','required min="0" step="0.01"'),area('note','Closing note / reason for a cash difference'))}<div id="closing-preview" class="notice" style="margin:18px 0">Expected cash: ${money(n.expected)}</div><button type="submit" class="btn primary">${icon('check')} Close today</button></form>`)}${card('Before you close',`<div class="card-body"><div class="check-list">${['Save all bills and payments.','Record purchases and attach receipts.','Count cash and check UPI / card totals.','Check customer dues and tomorrow’s bookings.','Save staff attendance and leave records.','Check low stock and contact suppliers.','Turn off unused lights, AC and equipment.','Share the day’s report with the owner.'].map((t,i)=>check('daily-check-'+i,t)).join('')}</div><p class="fine-print">These reminders are for your check. The cash closing is saved in the records.</p></div>`)}</div>`+card('Past closings',table(['Date','Expected','Counted','Difference','Status',''],[...A.data.closures].reverse().map(c=>`<tr><td>${niceDate(c.date)}</td><td>${money(c.expected)}</td><td>${money(c.actual)}</td><td>${money(c.difference)}</td><td>${badge(c.reopenedAt?'Reopened':'Closed',c.reopenedAt?'warn':'')}</td><td>${!c.reopenedAt&&A.user.role==='owner'?btn('Reopen','reopen-day','small',`data-id="${c.id}"`):''}</td></tr>`)));}
let modalSave=null,lastFocus=null;
function modal(titleText,body,save=null,saveLabel='Save',wide=false){lastFocus=document.activeElement;modalSave=save;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(titleText)}</h2>${btn(icon('close'),'close-modal','icon-btn','aria-label="Close dialog"')}</div><form id="modal-form"><div class="modal-body">${body}<div id="modal-error"></div></div><div class="modal-foot">${btn(save?'Cancel':'Close','close-modal','')}${save?`<button type="submit" class="btn primary">${saveLabel}</button>`:''}</div></form></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#modal-root input, #modal-root select, #modal-root button')?.focus(),30);}
function closeModal(){if(A.busy)return;$('#modal-root').innerHTML='';document.body.style.overflow='';modalSave=null;lastFocus?.focus();}
