function productForm(id){const r=id?find(A.data,'products',id):{taxBps:A.data.settings.defaultTaxBps};modal(id?'Edit product':'Add stock product',fields(input('name','Product name',r.name,'text','required'),input('sku','SKU / unique product code',r.sku,'text','required'),input('category','Category',r.category||'General'),input('unit','Stock unit (ml, bottle, piece)',r.unit||'unit','text','required'),input('price','Retail price per unit (₹)',rupees(r.price),'number','min="0" step="0.01"'),input('cost','Cost per unit (₹)',rupees(r.cost),'number','min="0" step="0.01"'),input('tax','Tax (%)',r.taxBps/100,'number','min="0" max="100" step="0.01"'),input('reorder','Reorder when stock reaches',r.reorder||0,'number','min="0" step="0.001"'),id?'':input('openingStock','Opening stock',0,'number','min="0" step="0.001"'),input('expiry','Earliest expiry date (optional)',r.expiry,'date'),input('supplier','Usual supplier',r.supplier),check('retail','Can be sold to customers',r.retail),check('active','Active product',r.active!==false))+`<div class="notice warn">For mixed expiry dates, use separate SKUs for each batch. Use Receive or Adjust to change stock after saving.</div>`,async(v,f)=>saveRecord('product.save',{...meta(id?r:null),...v,price:paise(v.price),cost:paise(v.cost),taxBps:Math.round(Number(v.tax)*100),retail:f.elements.retail.checked,active:f.elements.active.checked},'Product saved'),'Save product',true);}
