function purchaseForm(id){const p=A.data.products.find(x=>x.id===id);modal('Receive stock & record purchase',fields(select('productId','Product',opts('products'),id,'required'),input('qty','Quantity received','1','number','required min="0.001" step="0.001"'),input('unitCost','Unit cost (₹)',rupees(p?.cost),'number','required min="0" step="0.01"'),input('total','Bill total for this product (₹)','','number','required min="0" step="0.01"'),input('paid','Paid now (₹)','0','number','required min="0" step="0.01"'),select('method','Paid through',methods,'cash'),input('supplier','Supplier',p?.supplier,'text','required'),input('billNumber','Supplier bill number','','text','required'),input('date','Purchase / payment date',day(),'date',`required max="${day()}"`),input('expiry','Expiry of this stock (optional)',p?.expiry,'date'),area('note','Note (record each product from a supplier bill separately)'),receiptField())+'<p class="fine-print">The total may include delivery or tax. Stock cost uses the unit cost you enter. If expiry dates differ, receive into a separate batch SKU.</p>',async(v,f)=>saveRecord('purchase.create',{...v,qty:Number(v.qty),unitCost:paise(v.unitCost),total:paise(v.total),paid:paise(v.paid),attachment:await readAttachment(f)},'Purchase saved and stock updated'),'Receive stock',true);}
