function invoiceHtml(i){const s=i.business;const pays=A.data.payments.filter(p=>p.invoiceId===i.id);return `<article class="invoice"><header class="invoice-head"><div><p class="eyebrow">${DEMO?'DEMO · NOT A REAL BILL':'RECEIPT / INVOICE'}</p><h1>${esc(s.salonName)}</h1><p>${esc(s.address).replaceAll('\n','<br>')}</p><p>${esc(s.phone)}${s.gstin?' · GSTIN: '+esc(s.gstin):''}</p></div><div><strong>${esc(i.number)}</strong><p>${niceDate(i.date)}</p>${i.status==='void'?'<strong>CANCELLED</strong>':''}</div></header><div class="invoice-client"><strong>${esc(i.customerName)}</strong><p>${esc(i.customerPhone)}</p><p>Served by: ${esc(i.by)}</p></div>${table(['Service / product','Qty','Price','Discount','Net','Tax','Total'],i.lines.map(l=>`<tr><td>${esc(l.name)}<small>${l.staffName?' · '+esc(l.staffName):''}</small></td><td>${l.qty}</td><td>${money(l.price)}</td><td>${money(l.discount)}</td><td>${money(l.net)}</td><td>${money(l.tax)} (${l.taxBps/100}%)</td><td>${money(l.total)}</td></tr>`))}<div class="invoice-totals"><p>Before tax <strong>${money(i.net)}</strong></p><p>${esc(s.taxLabel)} <strong>${money(i.tax)}</strong></p><p class="grand">Total <strong>${money(i.total)}</strong></p><p>Received (less refunds) <strong>${money(pays.reduce((n,p)=>n+p.amount,0))}</strong></p><p>Balance due <strong>${money(balance(A.data,i.id))}</strong></p></div><h3>Payment history</h3>${table(['Date','Method','Amount','Reference'],pays.map(p=>`<tr><td>${niceDate(p.date)}</td><td>${esc(p.method.toUpperCase())}</td><td>${money(p.amount)}</td><td>${esc(p.reference)}</td></tr>`))}<p>${esc(i.note)}</p>${i.status==='void'?`<p>Cancellation reason: ${esc(i.voidReason)}</p>`:''}<footer><strong>${esc(s.receiptNote)}</strong><p>Please follow the care advice given by your service professional.</p></footer></article>`;}
function invoiceModal(id){const i=find(A.data,'invoices',id);modal('Invoice '+i.number,`<div class="actions" style="margin-bottom:18px">${btn(icon('print')+'Print / save PDF','print-invoice','',`data-id="${id}"`)}${balance(A.data,id)>0?btn('Receive payment','receive-payment','primary',`data-id="${id}"`):''}${A.user.role==='owner'&&i.status==='posted'?btn('Cancel bill','void-invoice','danger',`data-id="${id}"`):''}</div>`+invoiceHtml(i),null,'',true);}
